		.put("olmlet", Reason.HUMANOID)
		.put("ric", Reason.HUMANOID)
		.put("rift guardian", Reason.HUMANOID)
		.put("rock golem", Reason.HUMANOID)
		.put("skotos", Reason.HUMANOID)
		.put("smol heredit", Reason.HUMANOID)
		.put("tektiny", Reason.HUMANOID)
		.put("tumeken's damaged guardian", Reason.HUMANOID)
		.put("tumeken's guardian", Reason.HUMANOID)
		.put("tzrek-zuk", Reason.HUMANOID)
		.put("vet'ion jr.", Reason.HUMANOID)
		.put("yami", Reason.HUMANOID)
		.put("zilyana jr.", Reason.HUMANOID)
		// Snakes and worms
		.put("huberte", Reason.SLITHERS)
		.put("jal-nib-rek", Reason.SLITHERS)
		.put("lil'viathan", Reason.SLITHERS)
		.put("snakeling", Reason.SLITHERS)
		// Water creatures
		.put("kraken", Reason.AQUATIC)
		.put("tiny tempor", Reason.AQUATIC)
		// Not shaped for riding
		.put("baron", Reason.SHAPE)
		.put("kephriti", Reason.SHAPE)
		.put("muphin", Reason.SHAPE)
		.put("smoke devil", Reason.SHAPE)
		.put("vasa minirio", Reason.SHAPE)
		.build();

	/** Pet forms refused even though other forms of the same pet can be ridden (by NPC id). */
	private static final Map<Integer, Reason> NOT_RIDEABLE_FORMS = ImmutableMap.of(
		6637, Reason.HUMANOID // Kalphite Princess, upright winged form (the crawling form can be ridden)
	);

	/** Pets checked and tuned as mounts, by their in-game name (lower case). */
	private static final Set<String> RIDEABLE = ImmutableSet.of(
		"babi", "baby chinchompa", "baby mole", "baby mole-rat", "beaver", "beef", "bernese mountain dog",
		"bernese mountain dog puppy", "bloodhound", "bone squirrel", "border collie", "border collie puppy",
		"broav", "callisto cub", "cat", "chaos elemental jr.", "chihuahua", "chihuahua puppy", "chompy chick",
		"clockwork cat", "corgi", "corgi puppy", "corporeal critter", "corrupted youngllef", "dark core",
		"dark squirrel", "dom", "flying vespina", "fox", "giant squirrel", "great blue heron", "greyhound",
		"greyhound puppy", "gull", "gulliver", "hell-kitten", "hellcat", "hellpuppy", "herbi", "heron", "husky",
		"husky puppy", "ikkle hydra", "jalrek-jad", "kalphite princess", "kitten", "labrador", "labrador puppy",
		"lazy cat", "lazy hellcat", "lil' nylo", "lil' sot", "lil' zik", "little parasite", "mr mcgroot", "nid",
		"overgrown cat", "overgrown hellcat", "penance pet", "pheasant", "phoenix", "prince black dragon", "pug",
		"pug puppy", "puppadile", "quetzin", "rax", "red", "rocky", "samoyed", "samoyed puppy",
		"scorpia's offspring", "scurry", "shiba", "shiba puppy", "soup", "spaniel", "spaniel puppy", "sraracha",
		"tzrek-jad", "venenatis spiderling", "vespina", "vorki", "wily cat", "wily hellcat", "wisp", "yorkie",
		"yorkie puppy", "youngllef", "zebo", "ziggy"
	);

	private PetRules()
	{
	}

	static String normalize(String name)
	{
		if (name == null)
		{
			return "";
		}
		return name
			.replaceAll("<[^>]*>", "")
			.replace(' ', ' ')
			.trim()
			.toLowerCase(Locale.ROOT);
	}

	static Set<String> parseList(String csv)
	{
		if (csv == null || csv.isBlank())
		{
			return new HashSet<>();
		}
		return Arrays.stream(csv.split("[,\\n]"))
			.map(PetRules::normalize)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toSet());
	}

	/**
	 * @param npcId      the pet's NPC id (some pets have forms that differ)
	 * @param name       pet name as shown in game
	 * @param shape      the pet's model measurements, or null if not loaded yet
	 * @param alwaysAllow names the player has chosen to allow
	 * @param neverAllow  names the player has chosen to block
	 */
	static Verdict check(int npcId, String name, Shape shape, Set<String> alwaysAllow, Set<String> neverAllow)
	{
		String n = normalize(name);

		if (alwaysAllow.contains(n))
		{
			return Verdict.RIDEABLE;
		}
		if (neverAllow.contains(n))
		{
			return Verdict.no(Reason.SHAPE);
		}

		Reason known = NOT_RIDEABLE_FORMS.getOrDefault(npcId, NOT_RIDEABLE.get(n));
		if (known != null)
		{
			return Verdict.no(known);
		}
		if (RIDEABLE.contains(n))
		{
			return Verdict.RIDEABLE;
		}

		// Unlisted pet: judge it by its shape.
		if (shape == null)
		{
			return Verdict.RIDEABLE;
		}
		if (shape.isTallAndThin())
		{
			return Verdict.no(Reason.HUMANOID);
		}
		return Verdict.RIDEABLE;
	}

	/** Measurements of a pet model in local units, before any enlarging. Model Y points down. */
	static final class Shape
	{
		final float height;   // ground to top
		final float lift;     // gap between ground and the lowest point of the model
		final float footprint; // larger of width and length

		Shape(float height, float lift, float footprint)
		{
			this.height = height;
			this.lift = lift;
			this.footprint = footprint;
		}

		/** Much taller than it is wide or long, like a person standing up. */
		boolean isTallAndThin()
		{
			// Measure the body itself, not the gap under a floating pet.
			float body = height - lift;
			return footprint > 0 && body > footprint * 1.8f;
		}
	}
}

package com.petmounts;

import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.client.util.Text;

/** Builds right-click entries for a player the way the game does: their options, name and combat level. */
final class PlayerMenu
{
	/** The game adds this to a menu type to push the option below "Walk here" (e.g. Attack outside PvP). */
	private static final int DEPRIORITIZED = 2000;

	private PlayerMenu()
	{
	}

	/** The menu action for one of the game's player option types, or null if it isn't a player option. */
	static MenuAction action(int type)
	{
		int id = type >= DEPRIORITIZED ? type - DEPRIORITIZED : type;
		if (id < MenuAction.PLAYER_FIRST_OPTION.getId() || id > MenuAction.PLAYER_EIGHTH_OPTION.getId())
		{
			return null;
		}
		return MenuAction.of(id);
	}

	static boolean deprioritized(int type)
	{
		return type >= DEPRIORITIZED;
	}

	/** "Name  (level-126)", coloured like the game: white name, level from green (lower) to red (higher). */
	static String target(Player player, int myLevel)
	{
		String name = player.getName() == null ? "" : Text.removeTags(player.getName());
		int level = player.getCombatLevel();
		return "<col=ffffff>" + name + levelColor(level - myLevel) + "  (level-" + level + ")";
	}

	static String levelColor(int difference)
	{
		if (difference < -9)
		{
			return "<col=00ff00>";
		}
		if (difference < -6)
		{
			return "<col=40ff00>";
		}
		if (difference < -3)
		{
			return "<col=80ff00>";
		}
		if (difference < 0)
		{
			return "<col=c0ff00>";
		}
		if (difference > 9)
		{
			return "<col=ff0000>";
		}
		if (difference > 6)
		{
			return "<col=ff4000>";
		}
		if (difference > 3)
		{
			return "<col=ff8000>";
		}
		if (difference > 0)
		{
			return "<col=ffc000>";
		}
		return "<col=ffff00>";
	}
}

package com.petmounts;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * Puts a player in a riding pose by swapping their movement animations for the pose, on your screen only, and
 * puts their own animations back afterwards.
 */
final class RiderPoser
{
	/** Frame counts of the pose animations, so held frames stay in range. */
	private final Map<Integer, Integer> frameCounts = new HashMap<>();

	private final Client client;
	/** The player's own movement animations while they're posed, or null. */
	private int[] saved;
	/** The pose animation last applied, and the frames it holds or loops, for {@link #hold}. */
	private int heldAnimation = -1;
	private int heldStart, heldEnd;
	private boolean controlsFrames;

	RiderPoser(Client client)
	{
		this.client = client;
	}

	/** Applies the pose. Cheap to call every tick. */
	void apply(Player player, RiderPose pose)
	{
		int anim = animationFor(player, pose);

		// If the game has reset the player's movement anims (e.g. after an equipment change),
		// capture the fresh set so we restore the right ones afterwards.
		if (saved == null || player.getWalkAnimation() != anim)
		{
			saved = new int[]{
				player.getIdlePoseAnimation(),
				player.getWalkAnimation(),
				player.getRunAnimation(),
				player.getIdleRotateLeft(),
				player.getIdleRotateRight(),
				player.getWalkRotateLeft(),
				player.getWalkRotateRight(),
				player.getWalkRotate180(),
			};
			anim = animationFor(player, pose);
		}

		player.setIdlePoseAnimation(anim);
		player.setWalkAnimation(anim);
		player.setRunAnimation(anim);
		player.setIdleRotateLeft(anim);
		player.setIdleRotateRight(anim);
		player.setWalkRotateLeft(anim);
		player.setWalkRotateRight(anim);
		player.setWalkRotate180(anim);

		int start = 0, end = 0;
		if (pose.controlsFrames())
		{
			int last = Math.max(0, frameCount(anim) - 1);
			start = Math.min(pose.getLoopStart(), last);
			end = Math.min(pose.getLoopEnd(), last);
		}
		if (player.getPoseAnimation() != anim)
		{
			player.setPoseAnimation(anim);
			player.setPoseAnimationFrame(start);
		}

		heldAnimation = anim;
		heldStart = start;
		heldEnd = end;
		controlsFrames = pose.controlsFrames();
		hold(player);
	}

	/**
	 * Makes sure the player is in the pose right now. Called just before the rider is drawn, because the game
	 * can move the player's animation on between ticks (for example when they start or stop walking), which
	 * would otherwise show for a frame as a twitch.
	 */
	void hold(Player player)
	{
		if (saved == null || heldAnimation == -1)
		{
			return;
		}
		if (player.getPoseAnimation() != heldAnimation)
		{
			player.setPoseAnimation(heldAnimation);
			player.setPoseAnimationFrame(heldStart);
		}
		// Some seated poses come from one-off emotes: hold one frame, or loop just the settled part.
		if (controlsFrames)
		{
			int frame = player.getPoseAnimationFrame();
			boolean single = heldStart >= heldEnd;
			if (single ? frame != heldStart : frame < heldStart || frame >= heldEnd)
			{
				player.setPoseAnimationFrame(heldStart);
			}
		}
	}

	/** Puts the player's own animations back. */
	void restore(Player player, boolean moving)
	{
		if (player == null || saved == null)
		{
			saved = null;
			return;
		}
		player.setIdlePoseAnimation(saved[0]);
		player.setWalkAnimation(saved[1]);
		player.setRunAnimation(saved[2]);
		player.setIdleRotateLeft(saved[3]);
		player.setIdleRotateRight(saved[4]);
		player.setWalkRotateLeft(saved[5]);
		player.setWalkRotateRight(saved[6]);
		player.setWalkRotate180(saved[7]);
		player.setPoseAnimation(moving ? saved[1] : saved[0]);
		player.setPoseAnimationFrame(0);
		saved = null;
		heldAnimation = -1;
	}

	/** Forgets the saved animations without touching the player (after logout or a world hop). */
	void forget()
	{
		saved = null;
		heldAnimation = -1;
	}

	private int animationFor(Player player, RiderPose pose)
	{
		if (pose == RiderPose.STANDING || pose.getAnimationId() == -1)
		{
			return saved != null ? saved[0] : player.getIdlePoseAnimation();
		}
		return pose.getAnimationId();
	}

	private int frameCount(int animationId)
	{
		Integer known = frameCounts.get(animationId);
		if (known != null)
		{
			return known;
		}
		Animation a = client.loadAnimation(animationId);
		if (a == null)
		{
			// Not loaded yet: don't remember that, or seated poses would be stuck on their first
			// (standing) frame. Leave the frames as they are until it loads.
			return Integer.MAX_VALUE;
		}
		int count = a.isMayaAnim() ? Math.max(1, a.getDuration()) : Math.max(1, a.getNumFrames());
		frameCounts.put(animationId, count);
		return count;
	}
}

package com.petmounts;

import java.awt.Point;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.List;

/** The outline around a set of points on screen (their convex hull). */
final class ScreenHull
{
	private ScreenHull()
	{
	}

	static Polygon of(List<Point> points)
	{
		List<Point> sorted = new ArrayList<>(points);
		sorted.sort((a, b) -> a.x != b.x ? Integer.compare(a.x, b.x) : Integer.compare(a.y, b.y));
		int n = sorted.size();
		Point[] hull = new Point[2 * n];
		int k = 0;
		for (int i = 0; i < n; i++)
		{
			while (k >= 2 && cross(hull[k - 2], hull[k - 1], sorted.get(i)) <= 0)
			{
				k--;
			}
			hull[k++] = sorted.get(i);
		}
		for (int i = n - 2, lower = k + 1; i >= 0; i--)
		{
			while (k >= lower && cross(hull[k - 2], hull[k - 1], sorted.get(i)) <= 0)
			{
				k--;
			}
			hull[k++] = sorted.get(i);
		}
		Polygon polygon = new Polygon();
		for (int i = 0; i < Math.max(0, k - 1); i++)
		{
			polygon.addPoint(hull[i].x, hull[i].y);
		}
		return polygon;
	}

	private static long cross(Point o, Point a, Point b)
	{
		return (long) (a.x - o.x) * (b.y - o.y) - (long) (a.y - o.y) * (b.x - o.x);
	}
}

package com.petmounts;

/**
 * Builds the saddle and blanket geometry for one mount, moulded to that pet's back.
 *
 * The game can't create new models from scratch, so the plugin loads a spare model and reshapes it into this
 * geometry (the same approach Rapid Mounts uses for its custom saddle). This class only produces the shape:
 * vertex positions, triangles and colours in model space (x sideways, y pointing down, z toward the tail),
 * centred on the seat point on the pet's back.
 *
 * The blanket and seat follow the pet's real back: each point is dropped onto the pet's model in its idle
 * pose, and where the body falls away the cloth hangs down the side instead of floating or sinking in.
 *
 * Every triangle is emitted in both windings so the thin leather and cloth look solid from either side.
 */
final class SaddleMesh
{
	/** Height of the pet's back at a point relative to the seat (up positive), or NaN where there's nothing. */
	interface Surface
	{
		float heightAt(float dx, float dz);
	}

	// Colours in the game's 16-bit HSL: hue (0-63), saturation (0-7), lightness (0-127).
	static final short LEATHER = hsl(6, 4, 38);
	static final short LEATHER_DARK = hsl(6, 3, 20);
	static final short STEEL = hsl(0, 0, 72);
	static final short GOLD = hsl(8, 5, 62);
	static final short SILVER = hsl(0, 0, 96);
	/** The biggest the blanket gets (half its width, and its length), however broad the pet's back. */
	static final float MAX_BLANKET_HALF_WIDTH = 44;
	static final float MAX_BLANKET_LENGTH = 66;

	private static final float BLANKET_GAP = 0.8f;
	private static final float BLANKET_THICKNESS = 1.2f;
	private static final float SEAT_THICKNESS = 3.0f;

	final float[] x;
	final float[] y;
	final float[] z;
	final int[] f1;
	final int[] f2;
	final int[] f3;
	final short[] color;
	int vertexCount;
	int faceCount;

	/** How far the top of the seat sits above the pet's back, so the rider sits on the saddle. */
	float seatThickness;

	private SaddleMesh(int maxVertices, int maxFaces)
	{
		x = new float[maxVertices];
		y = new float[maxVertices];
		z = new float[maxVertices];
		f1 = new int[maxFaces];
		f2 = new int[maxFaces];
		f3 = new int[maxFaces];
		color = new short[maxFaces];
	}

	/**
	 * @param surface    the pet's back around the seat
	 * @param seatHeight the seat's height above the ground
	 * @param wideSeat   the rider sits with knees spread wide, so the seat is a little wider
	 * @param saddle     include the leather saddle and stirrups (false = just the blanket, for sitting cross-legged)
	 * @param blanket    blanket colour
	 * @param trim       blanket edge colour
	 */
	static SaddleMesh build(Surface surface, float seatHeight, boolean wideSeat, boolean saddle,
		short blanket, short trim, int maxVertices, int maxFaces)
	{
		SaddleMesh m = new SaddleMesh(maxVertices, maxFaces);
		float back = backHalfWidth(surface, seatHeight);

		// The saddle is sized for the rider; the blanket is sized for the pet.
		float sw = Math.max(12, Math.min(wideSeat ? 24 : 19, back * 0.85f));
		float sl = 38;
		// The blanket covers the back but stays in proportion to the rider, even on very broad, flat pets.
		float bw = Math.max(sw + 5, Math.min(Math.min(sw + 12, MAX_BLANKET_HALF_WIDTH), back * 1.1f));
		float bl = Math.max(46, Math.min(MAX_BLANKET_LENGTH, bw * 1.6f));

		// Blanket: cloth over the back, hanging down both sides, with a trimmed edge.
		float[][] blanketGround = drape(surface, 9, 6, bw, bl);
		m.sheet(blanketGround, 9, 6, bw, bl, BLANKET_GAP, BLANKET_THICKNESS, 0, 0, blanket, trim);
		float onBlanket = BLANKET_GAP + BLANKET_THICKNESS + 0.3f;

		if (!saddle)
		{
			m.seatThickness = onBlanket - 0.3f;
			return m;
		}

		// Seat: leather on the blanket, with a raised cantle at the back and pommel at the front.
		float[][] seatGround = drape(surface, 7, 7, sw, sl);
		m.sheet(seatGround, 7, 7, sw, sl, onBlanket, SEAT_THICKNESS, 9, 6, LEATHER, LEATHER_DARK);
		m.seatThickness = seatGround[3][3] + onBlanket + SEAT_THICKNESS;

		// Stirrup straps and stirrups hanging from each side of the seat.
		float strap = 14;
		for (int side = -1; side <= 1; side += 2)
		{
			float sx = side * sw * 0.97f;
			float edge = seatGround[3][side < 0 ? 0 : 6] + onBlanket; // height of the seat's side edge
			float top = -edge + 1;
			m.box(sx - 1.2f, sx + 1.2f, top, top + strap, -2.5f, 2.5f, LEATHER_DARK);
			float sy = top + strap;
			m.box(sx - 3.5f, sx + 3.5f, sy, sy + 1.5f, -4.5f, 4.5f, STEEL);
			m.box(sx - 3.5f, sx - 2.5f, sy - 5, sy, -4.5f, 4.5f, STEEL);
			m.box(sx + 2.5f, sx + 3.5f, sy - 5, sy, -4.5f, 4.5f, STEEL);
		}

		// A small horn on the pommel.
		float front = -sl / 2 * 0.9f;
		float pommelTop = seatGround[0][3] + onBlanket + SEAT_THICKNESS + 6;
		m.box(-1.8f, 1.8f, -(pommelTop + 4), -(pommelTop - 1), front - 1.8f, front + 1.8f, trim);
		return m;
	}

	/**
	 * Gold or silver fittings for this pet. Gold suits warm-coloured pets (browns, oranges, reds, whites);
	 * silver suits grey, black and cool-coloured ones (blues, greens, purples), where gold clashes.
	 *
	 * @param faceColors the pet's face colours (Jagex HSL)
	 * @param alphas     face transparency, or null
	 */
	static short trimFor(short[] faceColors, byte[] alphas)
	{
		if (faceColors == null || faceColors.length == 0)
		{
			return GOLD;
		}
		int[] hues = new int[64];
		int[] lums = new int[128];
		int faces = 0, grey = 0, colourful = 0;
		for (int f = 0; f < faceColors.length; f++)
		{
			if (alphas != null && f < alphas.length && (alphas[f] & 0xFF) >= 254)
			{
				continue;
			}
			int c = faceColors[f] & 0xFFFF;
			int hue = (c >> 10) & 63, sat = (c >> 7) & 7, lum = c & 127;
			faces++;
			lums[lum]++;
			if (sat < 2)
			{
				grey++;
			}
			else
			{
				colourful++;
				hues[hue]++;
			}
		}
		if (faces == 0)
		{
			return GOLD;
		}
		int median = 0;
		int seen = lums[0];
		while (median < 127 && seen < (faces + 1) / 2)
		{
			median++;
			seen += lums[median];
		}
		if (grey > faces * 0.6f)
		{
			return median < 75 ? SILVER : GOLD; // grey and black pets; white ones keep gold
		}
		int hue = 0;
		for (int h = 1; h < 64; h++)
		{
			if (hues[h] > hues[hue])
			{
				hue = h;
			}
		}
		if (colourful > 0 && hue >= 17 && hue <= 56)
		{
			return SILVER; // greens, blues and purples
		}
		return median < 16 ? SILVER : GOLD; // near-black pets
	}

	/**
	 * Half the width of the pet's back at the seat: how far out from the middle the back stays roughly level
	 * before it falls away down the pet's side.
	 */
	static float backHalfWidth(Surface surface, float seatHeight)
	{
		float fall = Math.max(6, seatHeight * 0.25f);
		float widest = 0;
		for (int dir = -1; dir <= 1; dir += 2)
		{
			float reach = 0;
			for (float dx = 2; dx <= 80; dx += 2)
			{
				float h = surface.heightAt(dir * dx, 0);
				if (Float.isNaN(h) || h < -fall)
				{
					break;
				}
				reach = dx;
			}
			widest = Math.max(widest, reach);
		}
		return Math.max(10, widest);
	}

	/**
	 * Heights of the back on a grid (rows front to back, columns left to right), relative to the seat.
	 * Working out from the middle of each row: where the body drops away or there's nothing below, the cloth
	 * hangs down instead of following the surface to the ground or up onto a raised part.
	 */
	private static float[][] drape(Surface surface, int nx, int nz, float halfW, float length)
	{
		float[][] g = new float[nz][nx];
		int mid = nx / 2;
		float dx = 2 * halfW / (nx - 1);
		float prevCentre = 0;
		for (int j = 0; j < nz; j++)
		{
			float pz = (j / (float) (nz - 1) * 2 - 1) * length / 2;
			float c = surface.heightAt(0, pz);
			if (Float.isNaN(c) || Math.abs(c - prevCentre) > length * 0.5f)
			{
				c = prevCentre;
			}
			g[j][mid] = c;
			prevCentre = c;
			for (int dir = -1; dir <= 1; dir += 2)
			{
				float prev = c;
				for (int k = 1; k <= mid; k++)
				{
					int i = mid + dir * k;
					float px = (i / (float) (nx - 1) * 2 - 1) * halfW;
					float h = surface.heightAt(px, pz);
					float hang = prev - dx * (0.4f + 0.25f * k); // drapes more steeply further out
					if (Float.isNaN(h) || h > prev + dx * 0.4f || h < prev - dx * 1.4f)
					{
						h = hang;
					}
					g[j][i] = h;
					prev = h;
				}
			}
		}
		return g;
	}

	/** A shell over a height grid: underside `lift` above the grid, `thickness` thick, with raised ends. */
	private void sheet(float[][] ground, int nx, int nz, float halfW, float length, float lift, float thickness,
		float cantle, float pommel, short main, short edge)
	{
		int top = vertexCount;
		for (int layer = 0; layer < 2; layer++)
		{
			float up = lift + (layer == 0 ? thickness : 0);
			for (int j = 0; j < nz; j++)
			{
				float t = j / (float) (nz - 1) * 2 - 1; // -1 front .. 1 back
				for (int i = 0; i < nx; i++)
				{
					float s = i / (float) (nx - 1) * 2 - 1; // -1 left .. 1 right
					float middle = 1 - s * s;
					float raise = t > 0 ? cantle * t * t * t * middle : pommel * -t * -t * -t * middle;
					vertex(s * halfW, -(ground[j][i] + up + raise), t * length / 2);
				}
			}
		}
		int bottom = top + nx * nz;
		for (int j = 0; j < nz - 1; j++)
		{
			for (int i = 0; i < nx - 1; i++)
			{
				boolean rim = i == 0 || j == 0 || i == nx - 2 || j == nz - 2;
				short c = rim ? edge : main;
				int a = j * nx + i, b = a + 1, d = a + nx, e = d + 1;
				quad(top + a, top + b, top + e, top + d, c);
				quad(bottom + a, bottom + b, bottom + e, bottom + d, c);
			}
		}
		// Close the edges so the shell has visible thickness.
		for (int i = 0; i < nx - 1; i++)
		{
			quad(top + i, top + i + 1, bottom + i + 1, bottom + i, edge);
			int back = (nz - 1) * nx;
			quad(top + back + i, top + back + i + 1, bottom + back + i + 1, bottom + back + i, edge);
		}
		for (int j = 0; j < nz - 1; j++)
		{
			int l = j * nx, l2 = l + nx, r = l + nx - 1, r2 = r + nx;
			quad(top + l, top + l2, bottom + l2, bottom + l, edge);
			quad(top + r, top + r2, bottom + r2, bottom + r, edge);
		}
	}

	/** An axis-aligned box. y values are model y (down positive). */
	private void box(float x0, float x1, float y0, float y1, float z0, float z1, short c)
	{
		int v = vertexCount;
		vertex(x0, y0, z0);
		vertex(x1, y0, z0);
		vertex(x1, y1, z0);
		vertex(x0, y1, z0);
		vertex(x0, y0, z1);
		vertex(x1, y0, z1);
		vertex(x1, y1, z1);
		vertex(x0, y1, z1);
		quad(v, v + 1, v + 2, v + 3, c);
		quad(v + 4, v + 5, v + 6, v + 7, c);
		quad(v, v + 1, v + 5, v + 4, c);
		quad(v + 3, v + 2, v + 6, v + 7, c);
		quad(v, v + 3, v + 7, v + 4, c);
		quad(v + 1, v + 2, v + 6, v + 5, c);
	}

	private void vertex(float px, float py, float pz)
	{
		if (vertexCount >= x.length)
		{
			return;
		}
		x[vertexCount] = px;
		y[vertexCount] = py;
		z[vertexCount] = pz;
		vertexCount++;
	}

	private void quad(int a, int b, int c, int d, short col)
	{
		tri(a, b, c, col);
		tri(a, c, d, col);
	}

	private void tri(int a, int b, int c, short col)
	{
		if (faceCount + 2 > f1.length || a >= vertexCount || b >= vertexCount || c >= vertexCount)
		{
			return;
		}
		// Both windings, so the face is visible from either side.
		f1[faceCount] = a;
		f2[faceCount] = b;
		f3[faceCount] = c;
		color[faceCount++] = col;
		f1[faceCount] = a;
		f2[faceCount] = c;
		f3[faceCount] = b;
		color[faceCount++] = col;
	}

	static short hsl(int hue, int sat, int lum)
	{
		return (short) ((hue & 63) << 10 | (sat & 7) << 7 | (lum & 127));
	}
}

package com.petmounts;

import net.runelite.client.config.ConfigManager;

/**
 * Adjustments the player has saved for one pet (by name, so every colour of a pet shares them):
 * size, seat height, seat forward/back and riding pose. Set from the Mount Stable panel.
 */
final class PetTweaks
{
	static final PetTweaks NONE = new PetTweaks(100, 0, 0, RiderPose.AUTO);
	/** Config keys holding saved adjustments start with this. */
	static final String KEY_PREFIX = "tweak_";

	final int size;
	final int seatHeight;
	final int seatForward;
	final RiderPose pose;

	PetTweaks(int size, int seatHeight, int seatForward, RiderPose pose)
	{
		this.size = Math.max(60, Math.min(160, size));
		this.seatHeight = Math.max(-40, Math.min(40, seatHeight));
		this.seatForward = Math.max(-60, Math.min(60, seatForward));
		this.pose = pose == null ? RiderPose.AUTO : pose;
	}

	boolean isDefault()
	{
		return size == 100 && seatHeight == 0 && seatForward == 0 && pose == RiderPose.AUTO;
	}

	static PetTweaks load(ConfigManager configManager, String petName)
	{
		String raw = configManager.getConfiguration(PetMountsConfig.GROUP, key(petName));
		if (raw == null || raw.isEmpty())
		{
			return NONE;
		}
		try
		{
			String[] p = raw.split(";");
			return new PetTweaks(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]),
				RiderPose.valueOf(p[3]));
		}
		catch (RuntimeException e)
		{
			return NONE;
		}
	}

	static void save(ConfigManager configManager, String petName, PetTweaks t)
	{
		if (t.isDefault())
		{
			configManager.unsetConfiguration(PetMountsConfig.GROUP, key(petName));
		}
		else
		{
			configManager.setConfiguration(PetMountsConfig.GROUP, key(petName),
				t.size + ";" + t.seatHeight + ";" + t.seatForward + ";" + t.pose.name());
		}
	}

	private static String key(String petName)
	{
		return KEY_PREFIX + PetRules.normalize(petName).replaceAll("[^a-z0-9]+", "_");
	}
}

package com.petmounts;

/**
 * Finds a seat on a pet the plugin has no tuned seat for (for example a pet released after this version).
 *
 * It drops a line straight down through the middle of the pet's body and takes the highest solid triangle it
 * hits: that point on the pet's back is where the rider sits. The same method was used, on the game's models,
 * to build {@link MountFits}.
 *
 * Coordinates are model space: x sideways, y pointing down, z toward the tail.
 */
final class SeatFinder
{
	/** Faces at least this transparent are effects (smoke, glow), not something to sit on. */
	static final int SOLID_ALPHA = 128;

	static final class Seat
	{
		final int a, b, c;
		final float wa, wb, wc;
		/** Height of the seat above the model's origin (up is positive). */
		final float height;

		Seat(int a, int b, int c, float wa, float wb, float wc, float height)
		{
			this.a = a;
			this.b = b;
			this.c = c;
			this.wa = wa;
			this.wb = wb;
			this.wc = wc;
			this.height = height;
		}
	}

	private SeatFinder()
	{
	}

	/**
	 * @param alphas face transparency (0 = opaque, 255 = invisible), or null if every face is opaque
	 * @return the seat under the middle of the body, or null if nothing solid was found
	 */
	static Seat find(float[] xs, float[] ys, float[] zs, int vertexCount,
		int[] f1, int[] f2, int[] f3, byte[] alphas, int faceCount)
	{
		// Seat front-to-back: the middle of the body's surface area. Thin necks and tails count for little.
		double areaSum = 0, zSum = 0;
		for (int f = 0; f < faceCount; f++)
		{
			if (!solid(alphas, f))
			{
				continue;
			}
			int a = f1[f], b = f2[f], c = f3[f];
			double ux = xs[b] - xs[a], uy = ys[b] - ys[a], uz = zs[b] - zs[a];
			double vx = xs[c] - xs[a], vy = ys[c] - ys[a], vz = zs[c] - zs[a];
			double cx = uy * vz - uz * vy, cy = uz * vx - ux * vz, cz = ux * vy - uy * vx;
			double area = Math.sqrt(cx * cx + cy * cy + cz * cz);
			areaSum += area;
			zSum += area * (zs[a] + zs[b] + zs[c]) / 3.0;
		}
		if (areaSum <= 0)
		{
			return null;
		}
		float seatZ = (float) (zSum / areaSum);

		// Seat side-to-side: the body's centre line, unless the model is built off-centre.
		float minX = Float.MAX_VALUE, maxX = -Float.MAX_VALUE;
		for (int v = 0; v < vertexCount; v++)
		{
			if (Math.abs(zs[v] - seatZ) < 8)
			{
				minX = Math.min(minX, xs[v]);
				maxX = Math.max(maxX, xs[v]);
			}
		}
		float seatX = 0;
		if (minX <= maxX)
		{
			float mid = (minX + maxX) / 2, half = (maxX - minX) / 2;
			seatX = Math.abs(mid) < 0.3f * half ? 0 : mid;
		}

		// Step sideways if the line slips through a gap between triangles.
		for (float dx : new float[]{0, 2, -2, 5, -5, 9, -9})
		{
			Seat s = raycast(xs, ys, zs, f1, f2, f3, alphas, faceCount, seatX + dx, seatZ);
			if (s != null)
			{
				return s;
			}
		}
		return null;
	}

	/** The highest solid triangle directly under (x, z). */
	static Seat raycast(float[] xs, float[] ys, float[] zs, int[] f1, int[] f2, int[] f3,
		byte[] alphas, int faceCount, float x, float z)
	{
		return raycast(xs, ys, zs, f1, f2, f3, alphas, faceCount, x, z, Float.MAX_VALUE);
	}

	/** The highest solid triangle directly under (x, z) that is no higher than maxHeight. */
	static Seat raycast(float[] xs, float[] ys, float[] zs, int[] f1, int[] f2, int[] f3,
		byte[] alphas, int faceCount, float x, float z, float maxHeight)
	{
		Seat best = null;
		for (int f = 0; f < faceCount; f++)
		{
			if (!solid(alphas, f))
			{
				continue;
			}
			int a = f1[f], b = f2[f], c = f3[f];
			float ax = xs[a], az = zs[a], bx = xs[b], bz = zs[b], cx = xs[c], cz = zs[c];
			float d = (bz - cz) * (ax - cx) + (cx - bx) * (az - cz);
			if (Math.abs(d) < 1e-6f)
			{
				continue; // seen edge-on from above
			}
			float wa = ((bz - cz) * (x - cx) + (cx - bx) * (z - cz)) / d;
			float wb = ((cz - az) * (x - cx) + (ax - cx) * (z - cz)) / d;
			float wc = 1 - wa - wb;
			if (wa < -1e-4f || wb < -1e-4f || wc < -1e-4f)
			{
				continue;
			}
			float height = -(wa * ys[a] + wb * ys[b] + wc * ys[c]);
			if (height > maxHeight)
			{
				continue;
			}
			if (best == null || height > best.height)
			{
				best = new Seat(a, b, c, wa, wb, wc, height);
			}
		}
		return best;
	}

	private static boolean solid(byte[] alphas, int face)
	{
		return alphas == null || (alphas[face] & 0xFF) < SOLID_ALPHA;
	}
}

